# hypothesis: a Final class attribute cannot be reassigned through the class object or an instance, and a Final[int | float] attribute reveals the declared union; CPython does not enforce Final, so the runtime accepts the lines that checkers must reject.
from typing import ClassVar, Final, final, reveal_type


class Config:
    LIMIT: Final[int | float] = 10
    registry: ClassVar[list[str]] = []


@final
class Leaf:
    def __init__(self, n: int) -> None:
        self.n: Final = n


def bump() -> float:
    Config.LIMIT = 11  # expect-error: reassigning a Final class attribute
    return Config.LIMIT


def add_name(name: str) -> None:
    Config.registry.append(name)


def read_leaf(leaf: Leaf) -> int:
    leaf.n = 3  # expect-error: reassigning a Final instance attribute
    return leaf.n


reveal_type(Config.LIMIT)
print(bump())
add_name('a')
print(read_leaf(Leaf(2)))
print(Config.registry)
